mapper.select:
select id, approval_type, status, run_id, agent_id, agent_version_id, workflow_id, workflow_version_id, node_key, requester_id, requester_type, request_reason, approver_id, decision_comment, decided_at, tool_key, risk_level, arguments_snapshot_json, arguments_digest, expire_at, created_at, updated_at from approval_request where 1 = 1
and status = #{status}
order by id desc limit #{pageSize} offset #{offset}
